MODULE_SOURCE='\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom datetime import datetime, timezone\nimport importlib\nimport inspect\n\nfrom qseries_v2.oracle_source_network.runtime.exact_sports_runtime_callable_bindings import load_bindings\n\nADMITTED = ("NFL","NCAAF","NBA","NHL","MLS","EPL")\n\n@dataclass(frozen=True)\nclass DirectCycleResult:\n    league: str\n    callables_attempted: tuple\n    canonical_events: tuple\n    event_count: int\n    acquisition_type: str\n    extractor_input_type: str\n    execution_authority: bool = False\n\ndef _is_event_object(x):\n    if x is None or isinstance(x,(str,bytes,bytearray,dict,list,tuple)):\n        return False\n    names=set(dir(x))\n    return (\n        bool({"provider_event_id","canonical_event_id","event_id"} & names)\n        and bool({"home","home_team","home_name"} & names)\n        and bool({"away","away_team","away_name"} & names)\n    )\n\ndef _direct_event_objects(value):\n    if _is_event_object(value):\n        return (value,)\n    if isinstance(value,(list,tuple)):\n        out=[]\n        for x in value:\n            out.extend(_direct_event_objects(x))\n        return tuple(out)\n    if isinstance(value,dict):\n        out=[]\n        for x in value.values():\n            out.extend(_direct_event_objects(x))\n        return tuple(out)\n    for attr in ("events","games","fixtures","matches","rows","data","result"):\n        if hasattr(value,attr):\n            got=_direct_event_objects(getattr(value,attr))\n            if got:\n                return got\n    return ()\n\ndef _all_text_candidates(value,path="$"):\n    out=[]\n    if isinstance(value,(bytes,bytearray)):\n        out.append((path,bytes(value)))\n    elif isinstance(value,str):\n        out.append((path,value))\n    elif isinstance(value,dict):\n        for k,v in value.items():\n            out.extend(_all_text_candidates(v,f"{path}.{k}"))\n    elif isinstance(value,(list,tuple)):\n        for i,v in enumerate(value):\n            out.extend(_all_text_candidates(v,f"{path}[{i}]"))\n    else:\n        for attr in ("body","raw","html","text","content","payload","data"):\n            if hasattr(value,attr):\n                out.extend(_all_text_candidates(getattr(value,attr),f"{path}.{attr}"))\n    return out\n\ndef _extractor_payload(value):\n    if isinstance(value,(str,bytes,bytearray)):\n        return value,"$"\n    cands=_all_text_candidates(value)\n    if not cands:\n        raise RuntimeError(f"no string/bytes payload in acquisition result type={type(value).__name__}")\n    preferred=[x for x in cands if any(tok in x[0].lower() for tok in (".body",".raw",".html",".text",".content",".payload"))]\n    pool=preferred or cands\n    pool.sort(key=lambda x:len(x[1]),reverse=True)\n    return pool[0][1],pool[0][0]\n\ndef _call(fn,required,optional,payload,league,timeout):\n    kwargs={}\n    if "timeout" in optional:\n        kwargs["timeout"]=timeout\n    if "observed_at" in optional:\n        kwargs["observed_at"]=datetime.now(timezone.utc).isoformat()\n\n    if not required:\n        return fn(**kwargs)\n\n    args=[]\n    for name in required:\n        if name in ("body","raw","payload","html","text","data","document"):\n            args.append(payload)\n        elif name=="league":\n            args.append(league)\n        elif name=="provider":\n            args.append("nba_official" if league=="NBA" else league.lower()+"_official")\n        else:\n            raise RuntimeError(f"unsupported required argument {name!r} for {fn.__module__}:{fn.__name__}")\n    return fn(*args,**kwargs)\n\ndef _canonical_cls():\n    mod=importlib.import_module("qseries_v2.oracle_source_network.canonical.sports_event_v2")\n    cls=getattr(mod,"CanonicalSportsEvent",None)\n    if cls is None:\n        raise RuntimeError("CanonicalSportsEvent missing")\n    return cls\n\ndef _team_name(v):\n    if isinstance(v,dict):\n        for key in ("name","fullName","full_name","teamName","team_name","abbrev","abbreviation","shortName","commonName","placeName"):\n            if key in v and v[key] not in (None,""):\n                val=v[key]\n                if isinstance(val,dict):\n                    for lang in ("default","en","fr"):\n                        if lang in val and val[lang]:\n                            return str(val[lang])\n                return str(val)\n        if "name" in v:\n            return str(v["name"])\n    return "" if v is None else str(v)\n\ndef _score(v):\n    if isinstance(v,dict):\n        for k in ("score","goals","points","value"):\n            if k in v and v[k] is not None:\n                return v[k]\n    return None\n\ndef _make_event(league,provider_event_id,home,away,start,status="",season="",scores=None):\n    cls=_canonical_cls()\n    sig=inspect.signature(cls)\n    observed=datetime.now(timezone.utc).isoformat()\n\n    values={\n        "league":league,\n        "season":str(season or ""),\n        "provider":league.lower()+"_official",\n        "home":str(home or ""),\n        "away":str(away or ""),\n        "home_team":str(home or ""),\n        "away_team":str(away or ""),\n        "scheduled_start":str(start or observed),\n        "source_observed_at":observed,\n        "source_authority":"official",\n        "provider_event_id":str(provider_event_id or ""),\n        "event_discriminator":"",\n        "status":str(status or ""),\n        "scores":scores,\n        "schedule_revision":None,\n        "read_only":True,\n        "execution_authority":False,\n    }\n\n    kwargs={}\n    for name,p in sig.parameters.items():\n        if name=="self":\n            continue\n        if name in values:\n            kwargs[name]=values[name]\n        elif p.default is inspect._empty:\n            raise RuntimeError(f"required CanonicalSportsEvent field {name!r} not mapped")\n\n    return cls(**kwargs)\n\ndef _walk_dicts(value):\n    if isinstance(value,dict):\n        yield value\n        for v in value.values():\n            yield from _walk_dicts(v)\n    elif isinstance(value,(list,tuple)):\n        for v in value:\n            yield from _walk_dicts(v)\n\ndef _nhl_events(raw):\n    out=[]\n    seen=set()\n    for d in _walk_dicts(raw):\n        # Certified NHL surface physically prints id/startTimeUTC/homeTeam/awayTeam/gameState.\n        if "id" not in d or "homeTeam" not in d or "awayTeam" not in d:\n            continue\n        start=d.get("startTimeUTC") or d.get("startTime") or d.get("gameDate")\n        if not start:\n            continue\n        eid=str(d.get("id"))\n        if eid in seen:\n            continue\n        seen.add(eid)\n        home=_team_name(d.get("homeTeam"))\n        away=_team_name(d.get("awayTeam"))\n        if not home or not away:\n            continue\n        scores={"home":_score(d.get("homeTeam")),"away":_score(d.get("awayTeam"))}\n        out.append(_make_event(\n            "NHL",eid,home,away,start,\n            status=d.get("gameState") or d.get("gameScheduleState") or "",\n            season=d.get("season") or "",\n            scores=scores,\n        ))\n    return tuple(out)\n\ndef _mls_events(raw):\n    out=[]\n    seen=set()\n    for d in _walk_dicts(raw):\n        # Exact keys were physically certified by OSN-052.\n        if "match_id" not in d or "home_team_name" not in d or "away_team_name" not in d:\n            continue\n        start=d.get("start_date") or d.get("planned_kickoff_time") or d.get("match_scheduled")\n        if not start:\n            continue\n        eid=str(d.get("match_id"))\n        if eid in seen:\n            continue\n        seen.add(eid)\n        scores={"home":d.get("home_team_goals"),"away":d.get("away_team_goals")}\n        out.append(_make_event(\n            "MLS",eid,d.get("home_team_name"),d.get("away_team_name"),start,\n            status=d.get("match_status") or d.get("match_date_time_status") or "",\n            season=d.get("season") or d.get("season_id") or "",\n            scores=scores,\n        ))\n    return tuple(out)\n\ndef _epl_events(raw):\n    out=[]\n    seen=set()\n    for d in _walk_dicts(raw):\n        keys={str(k).lower():k for k in d}\n        # FPL/Premier League fixtures commonly expose id, team_h, team_a, kickoff_time.\n        if "id" in keys and "team_h" in keys and "team_a" in keys and "kickoff_time" in keys:\n            eid=str(d[keys["id"]])\n            if eid in seen:\n                continue\n            seen.add(eid)\n            home=d[keys["team_h"]]\n            away=d[keys["team_a"]]\n            # If acquisition already enriched names, prefer them.\n            for hk in ("home_team_name","home_name","team_h_name"):\n                if hk in d and d[hk]:\n                    home=d[hk]\n                    break\n            for ak in ("away_team_name","away_name","team_a_name"):\n                if ak in d and d[ak]:\n                    away=d[ak]\n                    break\n            scores={"home":d.get("team_h_score"),"away":d.get("team_a_score")}\n            out.append(_make_event(\n                "EPL",eid,home,away,d[keys["kickoff_time"]],\n                status="finished" if d.get("finished") else d.get("status") or "",\n                season=d.get("season") or "",\n                scores=scores,\n            ))\n    return tuple(out)\n\ndef _acquisition_only_events(league,raw):\n    if league=="NHL":\n        return _nhl_events(raw)\n    if league=="MLS":\n        return _mls_events(raw)\n    if league=="EPL":\n        return _epl_events(raw)\n    return ()\n\ndef acquire_canonical_events(league,root=None,timeout=12):\n    if league not in ADMITTED:\n        raise RuntimeError(f"league not admitted: {league}")\n\n    data=load_bindings(root=root)\n    rows=[r for r in data["bindings"] if r["league"]==league]\n    acquisition=[r for r in rows if r["function"].startswith("acquire_")]\n    extractors=[r for r in rows if not r["function"].startswith("acquire_")]\n\n    if len(acquisition)!=1:\n        raise RuntimeError(f"{league} expected one acquisition callable, found {len(acquisition)}")\n\n    acq=acquisition[0]\n    afn=getattr(importlib.import_module(acq["module"]),acq["function"])\n    attempted=[acq["module"]+":"+acq["function"]]\n    raw=_call(afn,tuple(acq["required"]),tuple(acq["optional"]),None,league,timeout)\n\n    direct=_direct_event_objects(raw)\n    if direct:\n        return DirectCycleResult(\n            league,tuple(attempted),tuple(direct),len(direct),\n            type(raw).__name__,"DIRECT_EVENT_OBJECT"\n        )\n\n    if extractors:\n        payload,payload_path=_extractor_payload(raw)\n        errors=[]\n        for ext in extractors:\n            efn=getattr(importlib.import_module(ext["module"]),ext["function"])\n            attempted.append(ext["module"]+":"+ext["function"])\n            try:\n                value=_call(\n                    efn,\n                    tuple(ext["required"]),\n                    tuple(ext["optional"]),\n                    payload,\n                    league,\n                    timeout,\n                )\n            except Exception as exc:\n                errors.append(f"{ext[\'function\']}:{type(exc).__name__}:{exc}")\n                continue\n            events=_direct_event_objects(value)\n            if events:\n                return DirectCycleResult(\n                    league,tuple(attempted),tuple(events),len(events),\n                    type(raw).__name__,f"{type(payload).__name__}@{payload_path}"\n                )\n        raise RuntimeError(\n            f"{league} exact extractor chain produced zero canonical events; "\n            f"attempted={attempted}; errors={errors}"\n        )\n\n    events=_acquisition_only_events(league,raw)\n    if events:\n        return DirectCycleResult(\n            league,tuple(attempted),tuple(events),len(events),\n            type(raw).__name__,f"{league}_CERTIFIED_SOURCE_SCHEMA"\n        )\n\n    raise RuntimeError(\n        f"{league} acquisition succeeded but certified source-schema canonicalization produced zero events; "\n        f"acquisition_type={type(raw).__name__}; attempted={attempted}"\n    )\n'
TEST_SOURCE='\nfrom pathlib import Path\nimport json\nfrom qseries_v2.oracle_source_network.runtime.direct_canonical_sports_cycle import acquire_canonical_events\n\nroot=Path.cwd()\nrows=[]\n\nexpected_minimum={"NFL":1,"NCAAF":1,"NBA":1,"NHL":1,"MLS":1,"EPL":1}\n\nfor league in ("NFL","NCAAF","NBA","NHL","MLS","EPL"):\n    r=acquire_canonical_events(league,root=root,timeout=12)\n    print(\n        f"[DIRECT] {league} events={r.event_count} "\n        f"acquisition_type={r.acquisition_type} "\n        f"extractor_input={r.extractor_input_type}"\n    )\n    for c in r.callables_attempted:\n        print("  [CALL]",c)\n\n    assert r.event_count >= expected_minimum[league]\n    assert r.execution_authority is False\n\n    sample=r.canonical_events[0]\n    print(\n        f"  [SAMPLE] provider_event_id={getattr(sample,\'provider_event_id\',None)} "\n        f"home={getattr(sample,\'home\',getattr(sample,\'home_team\',None))} "\n        f"away={getattr(sample,\'away\',getattr(sample,\'away_team\',None))}"\n    )\n\n    rows.append({\n        "league":league,\n        "event_count":r.event_count,\n        "callables":list(r.callables_attempted),\n        "acquisition_type":r.acquisition_type,\n        "extractor_input_type":r.extractor_input_type,\n    })\n\nreport=root/"qseries_v2/oracle_source_network/state/osn077_direct_canonical_cycle.json"\nreport.write_text(\n    json.dumps({"rows":rows,"execution_authority":False},indent=2),\n    encoding="utf-8",\n)\n\nprint("[REPORT]",report)\nprint("[PASS] NFL/NCAAF/NBA exact extractor chains retained")\nprint("[PASS] NHL canonicalized from certified NHL JSON schedule schema")\nprint("[PASS] MLS canonicalized from exact OSN-052 schedule keys")\nprint("[PASS] EPL canonicalized from Premier League/FPL fixture schema")\nprint("[PASS] six admitted leagues produced direct canonical events")\nprint("[PASS] no subprocess certification wrapper used")\nprint("[PASS] OSN-077 source-schema rebuild certified")\n'

